import{_ as s,a0 as d,w as p,s as l,ao as n,I as o,x as t,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"完美生活：git rebase -i | LCTT x X-CMD","titleTemplate":false,"description":"完美生活：git rebase -i | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"完美生活：git rebase -i | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"完美生活：git rebase -i | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200429 The life-changing magic of git rebase -i","title":"完美生活：git rebase -i","tag":"202005","desc":""},"relativePath":"202005/20200429 The life-changing magic of git rebase -i.md","filePath":"[post].md"}'),g={name:"202005/20200429 The life-changing magic of git rebase -i.md"};function c(b,e,m,u,f,h){const i=d("Link");return p(),l("div",null,[e[15]||(e[15]=n('<h1 id="完美生活-git-rebase-i" tabindex="-1">完美生活：git rebase -i <a class="header-anchor" href="#完美生活-git-rebase-i" aria-label="Permalink to “完美生活：git rebase -i”">​</a></h1><blockquote><p>讓大家覺得你一次就能寫出完美的代碼，並讓你的補丁更容易審核和合並。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202005/18/185911fvwztwyp4lvbzkw4.jpg" alt=""></p><p>軟件開發是混亂的。有很多錯誤的轉折、有需要修復的錯別字、有需要修正的錯誤、有需要稍後糾正的臨時和粗陋的代碼，還有在以後的開發過程中發現一次又一次的問題。有了版本控制，在創建“完美”的最終產品（即準備提交給上游的補丁）的過程中，你會有一個記錄着每一個錯誤轉折和修正的原始記錄。就像電影中的花絮一樣，它們會讓人有點尷尬，有時也會讓人覺得好笑。</p><p>如果你使用版本控制來定期保存你的工作線索，然後當你準備提交審核的東西時，又可以隱藏所有這些私人草稿工作，並只提交一份單一的、完美的補丁，那不是很好嗎？<code>git rebase -i</code>，是重寫歷史記錄的完美方法，可以讓大家覺得你一次就寫出了完美的代碼！</p><h3 id="git-rebase-的作用是什麼" tabindex="-1">git rebase 的作用是什麼？ <a class="header-anchor" href="#git-rebase-的作用是什麼" aria-label="Permalink to “git rebase 的作用是什麼？”">​</a></h3><p>如果你不熟悉 Git 的複雜性，這裏簡單介紹一下。在幕後，Git 將項目的不同版本與唯一標識符關聯起來，這個標識符由父節點的唯一標識符的哈希以及新版本與其父節點的差異組成。這樣就形成了一棵修訂樹，每個簽出項目的人都會得到自己的副本。不同的人可以把項目往不同的方向發展，每個方向都可能從不同的分支點開始。</p><p><img src="https://opensource.com/sites/default/files/uploads/master-private-branches.png" alt="Master branch vs. private branch" title="Master branch vs. private branch"></p><p><em>左邊是 origin 版本庫中的主分支，右邊是你個人副本中的私有分支。</em></p><p>有兩種方法可以將你的工作與原始版本庫中的主分支整合起來：一種是使用合併：<code>git merge</code>，另一種是使用變基：<code>git rebase</code>。它們的工作方式非常不同。</p><p>當你使用 <code>git merge</code> 時，會在主分支（<code>master</code>）上創建一個新的提交，其中包括所有來自原始位置（<code>origin</code>）的修改和所有本地的修改。如果有任何衝突（例如，如果別人修改了你也在修改的文件），則將這些衝突標記出來，並且你有機會在將這個“合併提交”提交到本地版本庫之前解決這些衝突。當你將更改推送回父版本庫時，所有的本地工作都會以分支的形式出現在 Git 版本庫的其他用户面前。</p><p>但是 <code>git rebase</code> 的工作方式不同。它會回滾你的提交，並從主分支（<code>master</code>）的頂端再次重放這些提交。這導致了兩個主要的變化。首先，由於你的提交現在從一個不同的父節點分支出來，它們的哈希值會被重新計算，並且任何克隆了你的版本庫的人都可能得到該版本庫的一個殘破副本。第二，你沒有“合併提交”，所以在將更改重放到主分支上時會識別出任何合併衝突，因此，你需要在進行<ruby>變基<rt>rebase</rt></ruby>之前先修復它們。現在，當你現在推送你的修改時，你的工作不會出現在分支上，並且看起來像是你是在主分支的最新的提交上寫入了所有的修改。</p><p><img src="https://opensource.com/sites/default/files/uploads/merge-commit-vs-rebase.png" alt="Merge commits preserve history, and rebase rewrites history." title="Merge commits preserve history, and rebase rewrites history."></p><p><em>合併提交（左）保留了歷史，而變基（右）重寫歷史。</em></p><p>然而，這兩種方式都有一個缺點：在你準備好分享代碼之前，每個人都可以看到你在本地處理問題時的所有塗鴉和編輯。這就是 <code>git rebase</code> 的 <code>--interactive</code>（或簡寫 <code>-i</code>）標誌發揮作用的地方。</p><h3 id="git-rebase-i-登場" tabindex="-1">git rebase -i 登場 <a class="header-anchor" href="#git-rebase-i-登場" aria-label="Permalink to “git rebase -i 登場”">​</a></h3><p><code>git rebase</code> 的最大優點是它可以重寫歷史。但是，為什麼僅止於假裝你從後面的點分支出來呢？有一種更進一步方法可以重寫你是如何準備就緒這些代碼的：<code>git rebase -i</code>，即交互式的 <code>git rebase</code>。</p><p>這個功能就是 Git 中的 “魔術時光機” 功能。這個標誌允許你在做變基時對修訂歷史記錄進行復雜的修改。你可以隱藏你的錯誤! 將許多小的修改合併到一個嶄新的功能補丁中! 重新排列修改歷史記錄中的顯示順序！</p><p><img src="https://opensource.com/sites/default/files/uploads/git-rebase-i.png" alt="output of git rebase -i" title="output of git rebase -i"></p><p>當你運行 <code>git rebase -i</code> 時，你會進入一個編輯器會話，其中列出了所有正在被變基的提交，以及可以對其執行的操作的多個選項。默認的選擇是選擇（<code>Pick</code>）。</p><ul><li><code>Pick</code>：會在你的歷史記錄中保留該提交。</li><li><code>Reword</code>：允許你修改提交信息，可能是修復一個錯別字或添加其它註釋。</li><li><code>Edit</code>：允許你在重放分支的過程中對提交進行修改。</li><li><code>Squash</code>：可以將多個提交合併為一個。</li><li>你可以通過在文件中移動來重新排序提交。</li></ul><p>當你完成後，只需保存最終結果，變基操作就會執行。在你選擇修改提交的每個階段（無論是用 <code>reword</code>、<code>edit</code>、<code>squash</code> 還是發生衝突時），變基都會停止，並允許你在繼續提交之前進行適當的修改。</p><p>上面這個例子的結果是 “One-liner bug fix” 和 “Integate new header everywhere” 被合併到一個提交中，而 “New header for docs website” 和 “D&#39;oh - typo. Fixed” 合併到另一個提交中。就像變魔術一樣，其他提交的工作還在你的分支中，但相關的提交已經從你的歷史記錄中消失了！</p><p>這使得使用 <code>git send-email</code> 或者用你新整理好的補丁集在父版本庫中創建一個拉取請求，然後來提交一個乾淨的補丁給上游項目變得很容易。這有很多好處，包括讓你的代碼更容易審核，更容易接受，也更容易合併。</p><hr>',25)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),r(i,{href:"https://opensource.com/article/20/4/git-rebase-i"},{default:a(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/20/4/git-rebase-i",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("作者：",-1)),r(i,{href:"https://opensource.com/users/dneary"},{default:a(()=>[...e[2]||(e[2]=[t("Dave Neary",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),r(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),r(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),r(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),r(i,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const w=s(g,[["render",c]]);export{v as __pageData,w as default};
